insert into public.academy_trades (slug, name, family, icon, intro, seo_title, seo_description, sales_challenge, sort_order) values
  ('tree-removal', 'Tree Removal', 'Sitework', 'Axe', 'Tree removal companies win work by explaining risk, method and cleanup clearly, and they keep crews safe with planning and the right equipment. This classroom covers pricing trees by size and access, rigging and crane jobs, storm response, chipper and chainsaw safety, and building steady work with property managers and builders.', 'Tree Removal Business Courses', 'Tree removal business courses on pricing by size and access, crane and rigging jobs, storm work, stump grinding, crew safety and growth.', 'Homeowners often get tree removal quotes that look wildly different and can''t tell why. Walk the tree with them, explain the removal method, and list stump grinding and haul-away as separate choices so they compare the same scope.', 230),
  ('tree-trimming', 'Tree Trimming', 'Sitework', 'TreeDeciduous', 'Tree trimming companies earn steady work by pruning to clear goals, keeping customers on a regular cycle and working safely at height. This classroom covers quoting tree by tree, explaining pruning types, scheduling routes and seasons, climbing and aerial lift safety, and building recurring pruning customers.', 'Tree Trimming Business Courses', 'Tree trimming and pruning business courses on quoting tree by tree, pruning types, route scheduling, recurring customers and climbing safety.', 'Customers often can''t picture what trimming will look like and worry about over-pruning. Describe the pruning type and goal for each tree, show before and after examples, and offer a regular cycle so the trees stay healthy.', 240)
insert into public.academy_courses (id, slug, trade_slug, pillar, title, summary, description, level, access, status, content_class, cover_theme, featured, sort_order, planned_lessons, seo_title, seo_description, published_at) values
  (md5('academy:course:tree-removal-getting-started')::uuid, 'tree-removal-getting-started', 'tree-removal', 'getting_started', 'Starting a Tree Removal Business: Licensing, Insurance and Equipment', 'Business basics for a tree removal company, from insurance and licensing to the first truck and chipper.', 'Tree removal carries real risk to people and property, so insurance and the right setup come first. This course covers entity setup, general liability and workers'' compensation for tree work, arborist certification and local licensing where required, and choosing a first truck, chipper and stump grinder. Licensing and insurance requirements vary by state and city; confirm them with your licensing office and insurance agent.', 'beginner', 'public', 'upcoming', 'original', 'slate', false, 10, array['Entity setup and tax registration basics', 'Liability and workers'' compensation for tree work', 'Arborist certification and local licensing', 'Choosing a first truck, chipper and grinder', 'Setting a service area and minimum job']::text[], null, 'Business basics for a tree removal company, from insurance and licensing to the first truck and chipper.', null),
  (md5('academy:course:tree-removal-sales')::uuid, 'tree-removal-sales', 'tree-removal', 'sales', 'Selling Tree Removal: Explaining Risk, Method and Cleanup', 'Help homeowners compare quotes on scope and safety, not just price.', 'Tree removal quotes can differ by thousands of dollars for the same tree. This course covers walking the tree with the customer, explaining the removal method, offering stump grinding and haul-away as separate choices, and showing proof of insurance so the customer compares like for like.', 'intermediate', 'public', 'upcoming', 'original', 'cyan', false, 20, array['Walking the tree with the customer', 'Explaining climbing, rigging, bucket truck and crane methods', 'Offering stump grinding and haul-away as options', 'Showing insurance and certification', 'Following up on storm and hazard quotes']::text[], 'Selling Tree Removal: Explaining Risk, Method and Cleanup', 'Help homeowners compare quotes on scope and safety, not just price.', null),
  (md5('academy:course:tree-removal-estimating')::uuid, 'tree-removal-estimating', 'tree-removal', 'estimating', 'Tree Removal Estimates by Size, Access and Equipment', 'Price each tree from height, diameter and drop zone, with equipment and disposal on their own lines.', 'Height, trunk diameter, lean, and what sits under the tree drive most of the cost. This course covers estimating crew hours from your own production records, pricing rigging, bucket truck and crane time, stump grinding by diameter, and disposal, log hauling and wood chip haul-away.', 'intermediate', 'public', 'upcoming', 'original', 'navy', false, 30, array['Sizing a tree: height, diameter and lean', 'Pricing access and the drop zone', 'Equipment and crane time', 'Stump grinding and root work', 'Disposal, logs and wood chips']::text[], 'Tree Removal Estimates by Size, Access and Equipment', 'Price each tree from height, diameter and drop zone, with equipment and disposal on their own lines.', null),
  (md5('academy:course:tree-removal-project-management')::uuid, 'tree-removal-project-management', 'tree-removal', 'project_management', 'Planning Crane, Rigging and Storm Jobs', 'Plan crews, equipment and the site so complex removals go safely and on schedule.', 'Complex removals depend on planning before the saw starts. This course covers job briefings, coordinating crane and bucket truck time, calling for utility locates, protecting lawns and driveways, and running storm response when demand spikes.', 'intermediate', 'public', 'upcoming', 'original', 'green', false, 40, array['Pre-job site walk and briefing', 'Coordinating crane and equipment time', 'Utility locates and line clearance', 'Protecting lawns, driveways and structures', 'Running storm response']::text[], 'Planning Crane, Rigging and Storm Jobs', 'Plan crews, equipment and the site so complex removals go safely and on schedule.', null),
  (md5('academy:course:tree-removal-accounting')::uuid, 'tree-removal-accounting', 'tree-removal', 'accounting', 'Tree Service Financials: Equipment Costs and Job Costing', 'Track equipment, crew hours and disposal per job so every removal pays.', 'Trucks, chippers, grinders and cranes are a large share of a tree company''s costs. This course covers costing each job, setting equipment rates that cover payments and repairs, tracking dump and green waste fees, and planning cash flow around seasonal and storm work.', 'intermediate', 'public', 'upcoming', 'original', 'amber', false, 50, array['Job costing crew and climber hours', 'Setting equipment rates', 'Tracking disposal and dump fees', 'Seasonal and storm cash flow', 'Setting aside taxes and overhead']::text[], 'Tree Service Financials: Equipment Costs and Job Costing', 'Track equipment, crew hours and disposal per job so every removal pays.', null),
  (md5('academy:course:tree-removal-hr')::uuid, 'tree-removal-hr', 'tree-removal', 'hr', 'Hiring and Training Tree Crews and Climbers', 'Recruit, train and keep groundworkers and climbers who work safely.', 'Good climbers and groundworkers are hard to find and keep. This course covers recruiting, structured training from ground crew to climber, certification paths, fair pay for skill levels, and building a safety culture that keeps people. Employment rules vary by state; follow the laws where you operate.', 'beginner', 'public', 'upcoming', 'original', 'rose', false, 60, array['Recruiting groundworkers and climbers', 'Training from ground crew to climber', 'Certification paths', 'Pay by skill level', 'Building a safety culture']::text[], 'Hiring and Training Tree Crews and Climbers', 'Recruit, train and keep groundworkers and climbers who work safely.', null),
  (md5('academy:course:tree-removal-growth')::uuid, 'tree-removal-growth', 'tree-removal', 'growth', 'Growing a Tree Service: Storm Work, Builders and Property Managers', 'Build steady work beyond one-off removals.', 'Storm work is unpredictable, so steady relationships matter. This course covers partnering with builders for lot clearing, serving property managers and HOAs, turning removals into pruning customers, and asking for reviews and referrals after a clean job.', 'intermediate', 'public', 'upcoming', 'original', 'cyan', false, 70, array['Builder and lot clearing partnerships', 'Property managers and HOAs', 'Turning removals into pruning customers', 'Reviews and referrals', 'Preparing for storm season']::text[], null, 'Build steady work beyond one-off removals.', null),
  (md5('academy:course:tree-removal-safety')::uuid, 'tree-removal-safety', 'tree-removal', 'safety', 'Chainsaw, Chipper and Rigging Safety', 'Keep crews safe around saws, chippers, rigging and power lines.', 'Tree work is one of the more dangerous trades. This course covers protective equipment, chainsaw and chipper safety, drop zones and communication, rigging basics, and staying clear of power lines. Follow OSHA rules, the ANSI Z133 safety standard, equipment manuals and the rules where you work.', 'beginner', 'public', 'upcoming', 'original', 'slate', false, 80, array['Protective equipment', 'Chainsaw and chipper safety', 'Drop zones and crew communication', 'Rigging basics', 'Power line clearance']::text[], 'Chainsaw, Chipper and Rigging Safety', 'Keep crews safe around saws, chippers, rigging and power lines.', null),
  (md5('academy:course:tree-trimming-getting-started')::uuid, 'tree-trimming-getting-started', 'tree-trimming', 'getting_started', 'Starting a Tree Trimming Business: Insurance, Certification and Equipment', 'Business basics for a tree trimming and pruning company.', 'Trimming work happens at height and near homes, so insurance and training come first. This course covers entity setup, liability and workers'' compensation for tree work, arborist certification, and choosing climbing gear, a chipper and access equipment. Requirements vary by state and city; confirm them with your licensing office and insurance agent.', 'beginner', 'public', 'upcoming', 'original', 'slate', false, 10, array['Entity setup and tax registration basics', 'Liability and workers'' compensation', 'Arborist certification', 'Climbing gear, chipper and lift choices', 'Setting a service area and minimum job']::text[], null, 'Business basics for a tree trimming and pruning company.', null),
  (md5('academy:course:tree-trimming-sales')::uuid, 'tree-trimming-sales', 'tree-trimming', 'sales', 'Selling Tree Trimming: Explaining Pruning Goals', 'Help customers understand what each tree gets and why.', 'Customers worry about how a tree will look after trimming. This course covers walking the property, describing pruning types and goals in plain language, offering tree-by-tree options, and presenting a regular pruning cycle.', 'intermediate', 'public', 'upcoming', 'original', 'cyan', false, 20, array['Walking the property with the customer', 'Explaining pruning types in plain language', 'Tree-by-tree options', 'Before and after examples', 'Offering a pruning cycle']::text[], 'Selling Tree Trimming: Explaining Pruning Goals', 'Help customers understand what each tree gets and why.', null),
  (md5('academy:course:tree-trimming-estimating')::uuid, 'tree-trimming-estimating', 'tree-trimming', 'estimating', 'Tree Trimming Estimates, Tree by Tree', 'Price each tree by pruning type, size and access, with cleanup and haul-away listed.', 'Pruning prices depend on tree size, pruning type, and how hard the tree is to reach. This course covers estimating crew hours from your own records, pricing crown cleaning, thinning, raising and reduction, clearance work, equipment time, and brush and chip haul-away.', 'intermediate', 'public', 'upcoming', 'original', 'navy', false, 30, array['Pricing by pruning type', 'Size and access adjustments', 'Clearance and hedge work', 'Equipment and lift time', 'Cleanup and haul-away']::text[], 'Tree Trimming Estimates, Tree by Tree', 'Price each tree by pruning type, size and access, with cleanup and haul-away listed.', null),
  (md5('academy:course:tree-trimming-project-management')::uuid, 'tree-trimming-project-management', 'tree-trimming', 'project_management', 'Scheduling Trimming Routes and Pruning Seasons', 'Plan crews and routes around seasons, weather and customer cycles.', 'Trimming work follows seasons and repeat cycles. This course covers building efficient routes, timing pruning for species and season, coordinating access with customers, and keeping a schedule of repeat visits.', 'intermediate', 'public', 'upcoming', 'original', 'green', false, 40, array['Building efficient routes', 'Timing pruning by species and season', 'Customer access and notifications', 'Tracking repeat visits', 'Weather and reschedules']::text[], 'Scheduling Trimming Routes and Pruning Seasons', 'Plan crews and routes around seasons, weather and customer cycles.', null),
  (md5('academy:course:tree-trimming-accounting')::uuid, 'tree-trimming-accounting', 'tree-trimming', 'accounting', 'Tree Trimming Financials: Job Costing and Recurring Revenue', 'Know what each tree and each route really earns.', 'Small trimming jobs can lose money without clear costing. This course covers job costing crew hours, setting equipment rates, tracking disposal, billing recurring customers and reading profit by service type.', 'intermediate', 'public', 'upcoming', 'original', 'amber', false, 50, array['Job costing crew hours', 'Equipment rates', 'Disposal costs', 'Recurring billing', 'Profit by service type']::text[], 'Tree Trimming Financials: Job Costing and Recurring Revenue', 'Know what each tree and each route really earns.', null),
  (md5('academy:course:tree-trimming-hr')::uuid, 'tree-trimming-hr', 'tree-trimming', 'hr', 'Training Climbers and Ground Crews', 'Develop skilled, safe climbers and dependable ground crews.', 'Skilled climbers take time to develop. This course covers recruiting, structured training and mentoring, certification paths, pay by skill level and keeping crews. Employment rules vary by state; follow the laws where you operate.', 'beginner', 'public', 'upcoming', 'original', 'rose', false, 60, array['Recruiting ground crew', 'Mentoring new climbers', 'Certification paths', 'Pay by skill level', 'Keeping good crews']::text[], 'Training Climbers and Ground Crews', 'Develop skilled, safe climbers and dependable ground crews.', null),
  (md5('academy:course:tree-trimming-growth')::uuid, 'tree-trimming-growth', 'tree-trimming', 'growth', 'Building Recurring Pruning Customers', 'Turn one-time trims into yearly and multi-year pruning cycles.', 'Recurring pruning makes revenue predictable. This course covers offering pruning cycles, serving property managers, HOAs and commercial sites, seasonal promotions, and asking for reviews and referrals.', 'intermediate', 'public', 'upcoming', 'original', 'cyan', false, 70, array['Offering pruning cycles', 'Property managers and HOAs', 'Commercial grounds work', 'Seasonal promotions', 'Reviews and referrals']::text[], 'Building Recurring Pruning Customers', 'Turn one-time trims into yearly and multi-year pruning cycles.', null),
  (md5('academy:course:tree-trimming-safety')::uuid, 'tree-trimming-safety', 'tree-trimming', 'safety', 'Climbing, Aerial Lift and Power Line Safety', 'Work safely at height and stay clear of power lines.', 'Trimming puts crews at height with saws. This course covers protective equipment, climbing system inspections, aerial lift safety, drop zones, and minimum approach distances to power lines. Follow OSHA rules, the ANSI Z133 safety standard, equipment manuals and the rules where you work.', 'beginner', 'public', 'upcoming', 'original', 'slate', false, 80, array['Protective equipment', 'Climbing system inspections', 'Aerial lift safety', 'Drop zones and communication', 'Power line approach distances']::text[], 'Climbing, Aerial Lift and Power Line Safety', 'Work safely at height and stay clear of power lines.', null)
